/**
 * Writes app/theme.generated.css from theme.config.ts.
 * It runs before "npm run dev" and before "npm run build".
 */
import { writeFileSync } from "node:fs";
import { createTheme } from "@toraline/tokens";
import { themeInputs } from "../theme.config.ts";

const header =
  "/* Written by scripts/write-theme-css.ts from theme.config.ts. Do not edit this file. */\n";
const css = header + themeInputs.map((themeInput) => createTheme(themeInput)).join("\n");
const outputPath = new URL("../app/theme.generated.css", import.meta.url);

writeFileSync(outputPath, css);
console.log(`Wrote app/theme.generated.css with ${themeInputs.length} themes.`);
